const embedding = $input.item.json.embedding;
const vectorStr = '[' + embedding.join(',') + ']';
return { json: { embedding_str: vectorStr } };

const raw = String($('Execute Workflow Trigger').item.json.message.text || '');
const intent = String($json.intent || 'tool');
const similarity = Number($json.similarity || 0);

function normalize(str) {
  return str.toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\u0111/g, 'd')
    .replace(/\u0110/g, 'D');
}

const text = normalize(raw);
const hasGoldCue = /(vang|gold|sjc|9999)/.test(text);
const hasNewsCue = /(tin tuc|doc bao|bao hom nay|news|vnexpress|bao moi)/.test(text);
const hasWeatherCue = /(thoi tiet|weather|nhiet do|do am|mua|du bao|forecast)/.test(text);
const hasCalendarCue = /(calendar|google calendar|xem lich|lich hom nay|lich ngay mai|lich tuan nay|lich tuan sau|tao lich|dat lich|them lich|tao su kien|dat su kien|su kien|hop voi|meeting|kiem tra lich ranh|kiem tra lich ban|co ranh|ranh luc|xoa lich|huy lich|tim lich|cuoi tuan nay|cuoi tuan sau|thu [2-7]|chu nhat)/.test(text);
const hasGmailCue = /(gmail|xem mail|xem email|doc mail|doc email|gui mail|gui email|soan mail|soan email|tim mail|tim email|tra loi mail|tra loi email|inbox|hop thu|hop thu den|mail moi|email moi|check mail|check email|kiem tra mail|kiem tra email|send mail|send email|read mail|read email|reply mail|reply email|search mail|search email)/.test(text);
const hasSearchCue = /(tim|tra cuu|search|google|duckduckgo|wiki|wikipedia|cho toi biet|thong tin ve|noi ve)/.test(text);
const hasResearchCue = /(nghien cuu|paper|pubmed|journal|drug|interaction|gdp|imf|world bank|statista|bao cao|report|dataset)/.test(text);
const hasFactCue = /(ai la|la gi|o dau|nam nao|khi nao|bao nhieu|how|what|who|when|where)/.test(text);
const hasYearOrMetric = /(19\d{2}|20\d{2}|\d+\s*(usd|vnd|%|trieu|ty|billion|million))/i.test(text);

let routeIntent = intent;
let routeReason = `vector:${intent}:${similarity.toFixed(3)}`;

if (hasGoldCue || hasNewsCue || hasWeatherCue || hasCalendarCue || hasGmailCue) {
  routeIntent = 'tool';
  routeReason = 'keyword:direct_tool';
} else if ((hasSearchCue || hasResearchCue || hasFactCue || hasYearOrMetric) && similarity < 0.78) {
  routeIntent = 'tool';
  routeReason = 'keyword_override_search';
}

return [{
  json: {
    ...$json,
    raw,
    normalizedText: text,
    routeIntent,
    routeReason
  }
}];

