// TOOL ROUTER
// Them tool moi: 1 dong workflowMap + 1 dong detect
// =============================================
const workflowMap = {
  'gold':     'Sub-workflow: Giá Vàng',
  'news':     'Sub-workflow: Tin Tức',
  'search':   'Sub-workflow: Tìm Kiếm Web',
  'weather':  'Sub-workflow: Thời Tiết',
  'calendar': 'Sub-workflow: Google Calendar Master',
  'gmail':    'Sub-workflow: Google Gmail Master'
};

const raw = $('Execute Workflow Trigger').item.json.message.text;

function normalize(str) {
  return str.toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\u0111/g, 'd').replace(/\u0110/g, 'D');
}

const text = normalize(raw);

let toolKey = null;

if (text.includes('vang') || text.includes('gold') || text.includes('sjc')) {
  toolKey = 'gold';
} else if (text.includes('tin tuc') || text.includes('doc bao') || text.includes('bao hom nay') || text.includes('news')) {
  toolKey = 'news';
} else if (text.includes('thoi tiet') || text.includes('weather') || text.includes('nhiet do') || text.includes('do am') || text.includes('du bao')) {
  toolKey = 'weather';
} else if (/\b(calendar|google calendar|xem lich|lich hom nay|lich ngay mai|lich tuan nay|lich tuan sau|tao lich|dat lich|them lich|tao su kien|dat su kien|su kien|hop voi|meeting|kiem tra lich ranh|kiem tra lich ban|co ranh|ranh luc|xoa lich|huy lich|tim lich|cuoi tuan nay|cuoi tuan sau|thu [2-7]|chu nhat)\b/.test(text)) {
  toolKey = 'calendar';
} else if (/\b(gmail|xem mail|xem email|doc mail|doc email|gui mail|gui email|soan mail|soan email|tim mail|tim email|tra loi mail|tra loi email|inbox|hop thu|hop thu den|mail moi|email moi|check mail|check email|kiem tra mail|kiem tra email|send mail|send email|read mail|read email|reply mail|reply email|search mail|search email)\b/.test(text)) {
  toolKey = 'gmail';
} else if (text.includes('tim') || text.includes('search') || text.includes('tra cuu') || text.includes('cho toi biet') || text.includes('thong tin ve') || text.includes('duckduckgo') || text.includes('google')) {
  toolKey = 'search';
} else if (/[\d+\-*\/()%.]+/.test(text) && (text.includes('tinh') || text.includes('bang') || text.includes('cong') || text.includes('nhan') || text.includes('chia') || text.includes('tru'))) {
  const match = raw.match(/[\d+\-*\/().%\s]+/);
  if (match) {
    try {
      const result = eval(match[0].trim());
      return [{ json: { route: 'calc_done', response: 'Ket qua: ' + match[0].trim() + ' = ' + result, text: raw } }];
    } catch(e) {}
  }
  return [{ json: { route: 'calc_done', response: 'Khong the tinh duoc phep tinh nay.', text: raw } }];
}

if (toolKey) {
  return [{ json: { route: 'sub', workflowName: workflowMap[toolKey], text: raw } }];
}
return [{ json: { route: 'ai', text: raw } }];

const workflows = $input.item.json.data;
const targetName = $('Tool Router').item.json.workflowName;
const message = $('Execute Workflow Trigger').item.json.message;

const found = workflows.find(w => w.name === targetName);
if (!found) {
  // Fallback: return error response
  return [{ json: { workflowId: null, error: 'Workflow not found: ' + targetName, message } }];
}
return [{ json: { workflowId: found.id, message } }];

